+		if (!wrapped.ok) {
+			throw new CliError(wrapped.code, wrapped.message);
+		}
+	}
+	const unchanged = next === raw;
+	if (write && !unchanged) writeFileSync(absolute, next);
+	return {
+		wrote: write && !unchanged,
